/* ---- hydrate: fold the corpus layer into the library ---- */
function tmplRef(cl){
 const first = cl[0] || '';
 if(first.charAt(0)==='§') return 'Template ' + first.split(' ')[0];
 return 'Template ' + first.split(' ').slice(0,2).join(' ');
}
TYPES.forEach(t=>{
 t.template = TEMPLATES[t.id];
 t.issues.forEach((i,ix)=>{
  i.num = ix+1;
  i.ref = tmplRef(i.cl);
  const m = META[i.id] || [0,0,0];
  i.freq = m[0]; i.settled = m[1]; i.rounds = m[2];
  i.cpi = CPI.indexOf(i.id) >= 0 || !!(NEWPROV[t.id]||[]).find(x=>x.id===i.id);
  i.offPaper = !!(NEWPROV[t.id]||[]).find(x=>x.id===i.id);
  if(NOFB.indexOf(i.id) >= 0){ i.p = i.p.filter(x=>x.t.indexOf('Fallback')!==0); }
  else if(FB2[i.id]){
   const f = FB2[i.id], at = i.p.findIndex(x=>x.t==='Red line');
   i.p.splice(at, 0, P('Fallback 2', f[0], f[1], f[2]));
  }
  i.fb = i.p.filter(x=>x.t.indexOf('Fallback')===0).length;
 });
});

